// rows that actually have a Stripe subscription + a plan so the reporter
// never wastes a Stripe round-trip on trial/contract accounts.
func (q *Queries) ListAccountIDsWithActiveSubscription(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, listAccountIDsWithActiveSubscription)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

