const listSellingTerritories = `-- name: ListSellingTerritories :many
SELECT DISTINCT territory
FROM accounts
WHERE territory IS NOT NULL
  AND suspended_at IS NULL
`

// Every distinct territory somebody actually sells into.
//
// The contract sweep is shared work: a hospital's public contracts are the
// same public record for every supplier in that state, so two accounts in Mato
// Grosso cost one sweep, not two. Suspended accounts are excluded — sweeping
// for somebody who cannot log in spends a free government API's patience on
// nobody's behalf.
func (q *Queries) ListSellingTerritories(ctx context.Context) ([][]byte, error) {
	rows, err := q.db.Query(ctx, listSellingTerritories)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items [][]byte
	for rows.Next() {
		var territory []byte
		if err := rows.Scan(&territory); err != nil {
			return nil, err
		}
		items = append(items, territory)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

