const setStripeCustomerIfAbsent = `-- name: SetStripeCustomerIfAbsent :one
UPDATE accounts
SET stripe_customer_id = COALESCE(stripe_customer_id, $1),
    updated_at = NOW()
WHERE id = $2
RETURNING stripe_customer_id
`

type SetStripeCustomerIfAbsentParams struct {
	CustomerID *string `json:"customer_id"`
	ID         string  `json:"id"`
}

// Atomically claim a Stripe customer id for an account. COALESCE keeps any
// id already persisted, so two concurrent checkouts (each having minted a
// Stripe customer) converge on the first one written — the row lock
// serializes the writes and the loser's id is discarded by the caller.
// Returns the effective (winning) customer id.
func (q *Queries) SetStripeCustomerIfAbsent(ctx context.Context, arg SetStripeCustomerIfAbsentParams) (*string, error) {
	row := q.db.QueryRow(ctx, setStripeCustomerIfAbsent, arg.CustomerID, arg.ID)
	var stripe_customer_id *string
	err := row.Scan(&stripe_customer_id)
	return stripe_customer_id, err
}

