const updateAccountSubscription = `-- name: UpdateAccountSubscription :exec
UPDATE accounts
SET stripe_customer_id = COALESCE($2, stripe_customer_id),
    stripe_subscription_id = COALESCE($3, stripe_subscription_id),
    subscription_status = $4,
    -- Auto-manage past_due_at: stamp on first past_due, clear on recovery
    past_due_at = CASE
      WHEN $4 = 'past_due' AND past_due_at IS NULL THEN NOW()
      WHEN $4 != 'past_due' THEN NULL
      ELSE past_due_at
    END,
    updated_at = NOW()
WHERE id = $1
`

type UpdateAccountSubscriptionParams struct {
	ID                   string  `json:"id"`
	StripeCustomerID     *string `json:"stripe_customer_id"`
	StripeSubscriptionID *string `json:"stripe_subscription_id"`
	SubscriptionStatus   *string `json:"subscription_status"`
}

func (q *Queries) UpdateAccountSubscription(ctx context.Context, arg UpdateAccountSubscriptionParams) error {
	_, err := q.db.Exec(ctx, updateAccountSubscription,
		arg.ID,
		arg.StripeCustomerID,
		arg.StripeSubscriptionID,
		arg.SubscriptionStatus,
	)
	return err
}

