const usageTrendByAccount = `-- name: UsageTrendByAccount :many
WITH days AS (
    SELECT generate_series(
        date_trunc('day', NOW() - INTERVAL '29 days'),
        date_trunc('day', NOW()),
        INTERVAL '1 day'
    )::date AS day
)
SELECT
    days.day::date AS day,
    COALESCE(SUM(
        COALESCE((m.metadata->>'tokens_in')::bigint, 0) +
        COALESCE((m.metadata->>'tokens_out')::bigint, 0)
    ), 0)::bigint AS tokens,
    COUNT(DISTINCT m.conversation_id)::bigint AS conversations
FROM days
LEFT JOIN messages m ON date_trunc('day', m.created_at)::date = days.day
    AND m.conversation_id IN (
        SELECT id FROM conversations WHERE account_id = $1::char(26)
    )
GROUP BY days.day
ORDER BY days.day ASC
`

type UsageTrendByAccountRow struct {
	Day           pgtype.Date `json:"day"`
	Tokens        int64       `json:"tokens"`
	Conversations int64       `json:"conversations"`
}

// 30-day token + conversation count rollup for the owner-panel chart.
// tokens_in/tokens_out come from the messages.metadata JSONB stamped
// by the inbound pipeline; days with no AI messages return 0 (the
// generate_series ensures every day in the window has a row).
func (q *Queries) UsageTrendByAccount(ctx context.Context, accountID string) ([]UsageTrendByAccountRow, error) {
	rows, err := q.db.Query(ctx, usageTrendByAccount, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsageTrendByAccountRow
	for rows.Next() {
		var i UsageTrendByAccountRow
		if err := rows.Scan(&i.Day, &i.Tokens, &i.Conversations); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
